  exp.init(setupSphereEmitter3D.worldCfg(SRC));   // WORLD first, then parts
  exp.addObject('SphereEmitter', SRC);
  // The ten mirror SLABS at the star vertices — 3D walls (z-slab −SD/2..SD/2), each
